-- Recovered verbatim from the production Supabase migration ledger for L0 replay parity.
alter table public.hq_workforce_decisions add column if not exists run_id uuid references public.hq_workforce_runs(id) on delete set null;
create unique index if not exists hq_workforce_decisions_active_run_uq on public.hq_workforce_decisions(run_id) where status in ('pending','approved','revision_requested','executed','verified');
create or replace function public.hq_workforce_build_decision_inbox() returns integer language plpgsql security invoker set search_path=public as $$ declare r record; sid uuid; n integer:=0; begin for r in select wr.id run_id,wr.work_item_id,wr.lane_key,wr.worker_id,w.job_key,wi.title,wi.summary,wi.priority from public.hq_workforce_runs wr join public.hq_workforce_workers w on w.id=wr.worker_id join public.hq_work_items wi on wi.id=wr.work_item_id where wr.status='decision_required' and not exists(select 1 from public.hq_workforce_decisions d where d.run_id=wr.id and d.status in ('pending','approved','revision_requested','executed','verified')) loop sid:=public.hq_context_capture_company_snapshot('work-decision:'||r.run_id::text,'workforce_action_approval','Action requires human authority before execution.'); insert into public.hq_workforce_decisions(decision_key,worker_id,lane_key,job_key,run_id,proposed_action,reason,evidence_snapshot_id,risk,status) values('run:'||r.run_id::text,r.worker_id,r.lane_key,r.job_key,r.run_id,'process_work_item:'||r.work_item_id::text,coalesce(r.summary,r.title,'Work item requires approval.'),sid,case when r.priority='critical' then 'critical' when r.priority='high' then 'high' else 'normal' end,'pending'); n:=n+1; end loop; return n; end $$;
revoke all on function public.hq_workforce_build_decision_inbox() from public,anon,authenticated;
